"""Paper-facing WM3D world-model benchmark aggregation.

This module intentionally separates two kinds of rows:

* same_harness: generated by this repository on a fixed sample manifest.
* literature_protocol: official numbers from another paper/model card, useful
  for context but not an apples-to-apples leaderboard unless rerun here.
"""
from __future__ import annotations

import argparse
import csv
import json
from pathlib import Path
from typing import Any, Iterable, Mapping, Sequence


ROW_FIELDS = [
    "model",
    "suite",
    "comparison_type",
    "protocol",
    "source_url",
    "num_videos",
    "fvd",
    "psnr",
    "ssim_raw",
    "ssim_x100",
    "lpips_raw",
    "lpips_x100",
    "rgb_l1",
    "motion_rgb_l1",
    "motion_region_depth_l1",
    "motion_region_depth_change_l1",
    "depth_change_l1",
    "depth_change_cos",
    "real_action_depth_win_rate",
    "real_action_motion_region_depth_win_rate",
    "real_action_token_win_rate",
    "native3d_protocol",
]


def load_json(path: str | Path) -> Any:
    return json.loads(Path(path).read_text())


def _as_float(value: Any) -> float | None:
    if value is None:
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _scale_x100(raw: float | None, scaled: float | None = None) -> float | None:
    if scaled is not None:
        return scaled
    if raw is None:
        return None
    return raw * 100.0


def _unscale_x100(raw: float | None, scaled: float | None = None) -> float | None:
    if raw is not None:
        return raw
    if scaled is None:
        return None
    return scaled / 100.0


def _round_or_none(value: float | None, digits: int = 6) -> float | None:
    return None if value is None else round(float(value), digits)


def _metric(metrics: Mapping[str, Any], key: str) -> float | None:
    return _as_float(metrics.get(key))


def _native_evidence(native3d: Mapping[str, Any] | None) -> Mapping[str, Any]:
    if not native3d:
        return {}
    core = native3d.get("core_contribution")
    if not isinstance(core, Mapping):
        return {}
    evidence = core.get("evidence")
    return evidence if isinstance(evidence, Mapping) else {}


def _base_row(
    *,
    model: str,
    suite: str,
    comparison_type: str,
    protocol: str,
    source_url: str | None = None,
) -> dict[str, Any]:
    row = {field: None for field in ROW_FIELDS}
    row.update(
        {
            "model": model,
            "suite": suite,
            "comparison_type": comparison_type,
            "protocol": protocol,
            "source_url": source_url,
        }
    )
    return row


def build_our_rows(
    video_quality: Mapping[str, Any],
    native3d: Mapping[str, Any] | None,
    *,
    model_name: str,
    suite: str = "WM3D-OXE-val",
) -> list[dict[str, Any]]:
    """Convert WM3D evaluator JSON reports into paper-table rows."""
    mode = video_quality.get("mode", {})
    protocol = str(mode.get("fvd_protocol") or mode.get("metric_protocol") or "wm3d_video_quality")
    metrics_all = video_quality.get("metrics", {}).get("ALL", {})
    fvd_all = video_quality.get("fvd", {}).get("ALL", {})
    evidence = _native_evidence(native3d)

    ssim_raw = _metric(metrics_all, "model_ssim")
    lpips_raw = _metric(metrics_all, "model_lpips")
    row = _base_row(
        model=model_name,
        suite=suite,
        comparison_type="same_harness",
        protocol=protocol,
        source_url=None,
    )
    row.update(
        {
            "num_videos": _as_float(fvd_all.get("num_videos") or video_quality.get("counts", {}).get("ALL")),
            "fvd": _metric(fvd_all, "model_fvd"),
            "psnr": _metric(metrics_all, "model_psnr"),
            "ssim_raw": ssim_raw,
            "ssim_x100": _scale_x100(ssim_raw),
            "lpips_raw": lpips_raw,
            "lpips_x100": _scale_x100(lpips_raw),
            "rgb_l1": _metric(metrics_all, "model_rgb_l1"),
            "motion_rgb_l1": _metric(metrics_all, "model_motion_rgb_l1"),
            "motion_region_depth_l1": _as_float(evidence.get("motion_region_depth_l1")),
            "motion_region_depth_change_l1": _as_float(evidence.get("motion_region_depth_change_l1")),
            "depth_change_l1": _as_float(evidence.get("depth_change_l1")),
            "depth_change_cos": _as_float(evidence.get("depth_change_cos")),
            "real_action_depth_win_rate": _as_float(evidence.get("mean_depth_win_rate_vs_counterfactual")),
            "real_action_motion_region_depth_win_rate": _as_float(
                evidence.get("mean_motion_region_depth_win_rate_vs_counterfactual")
            ),
            "real_action_token_win_rate": _as_float(evidence.get("mean_token_win_rate_vs_counterfactual")),
            "native3d_protocol": "wm3d_native3d_counterfactual" if native3d else "missing",
        }
    )

    rows = [_normalize_row(row)]

    if "last_frame_fvd" in fvd_all or "last_frame_psnr" in metrics_all:
        last_ssim_raw = _metric(metrics_all, "last_frame_ssim")
        last_lpips_raw = _metric(metrics_all, "last_frame_lpips")
        last = _base_row(
            model="Last-frame repeat",
            suite=suite,
            comparison_type="internal_baseline",
            protocol=protocol,
            source_url=None,
        )
        last.update(
            {
                "num_videos": _as_float(fvd_all.get("num_videos") or video_quality.get("counts", {}).get("ALL")),
                "fvd": _metric(fvd_all, "last_frame_fvd"),
                "psnr": _metric(metrics_all, "last_frame_psnr"),
                "ssim_raw": last_ssim_raw,
                "ssim_x100": _scale_x100(last_ssim_raw),
                "lpips_raw": last_lpips_raw,
                "lpips_x100": _scale_x100(last_lpips_raw),
                "rgb_l1": _metric(metrics_all, "last_frame_rgb_l1"),
                "motion_rgb_l1": _metric(metrics_all, "last_frame_motion_rgb_l1"),
                "native3d_protocol": "not_applicable",
            }
        )
        rows.append(_normalize_row(last))

    return rows


def validate_literature_baseline(item: Mapping[str, Any]) -> None:
    required = ("model", "suite", "comparison_type", "source_url", "protocol", "metrics")
    for key in required:
        if key not in item or item[key] in (None, ""):
            raise ValueError(f"literature baseline missing required field: {key}")
    if not isinstance(item["metrics"], Mapping):
        raise ValueError("literature baseline metrics must be an object")
    if item["comparison_type"] not in {"literature_protocol", "same_harness_external"}:
        raise ValueError("comparison_type must be literature_protocol or same_harness_external")


def literature_baseline_to_row(item: Mapping[str, Any]) -> dict[str, Any]:
    validate_literature_baseline(item)
    metrics = item["metrics"]
    ssim_raw = _unscale_x100(_metric(metrics, "ssim_raw"), _metric(metrics, "ssim_x100"))
    ssim_x100 = _scale_x100(ssim_raw, _metric(metrics, "ssim_x100"))
    lpips_raw = _unscale_x100(_metric(metrics, "lpips_raw"), _metric(metrics, "lpips_x100"))
    lpips_x100 = _scale_x100(lpips_raw, _metric(metrics, "lpips_x100"))
    row = _base_row(
        model=str(item["model"]),
        suite=str(item["suite"]),
        comparison_type=str(item["comparison_type"]),
        protocol=str(item["protocol"]),
        source_url=str(item["source_url"]),
    )
    row.update(
        {
            "num_videos": _as_float(item.get("num_videos") or metrics.get("num_videos")),
            "fvd": _metric(metrics, "fvd"),
            "psnr": _metric(metrics, "psnr"),
            "ssim_raw": ssim_raw,
            "ssim_x100": ssim_x100,
            "lpips_raw": lpips_raw,
            "lpips_x100": lpips_x100,
            "rgb_l1": _metric(metrics, "rgb_l1"),
            "motion_rgb_l1": _metric(metrics, "motion_rgb_l1"),
            "native3d_protocol": str(item.get("native3d_protocol", "not_reported")),
        }
    )
    return _normalize_row(row)


def load_literature_baselines(path: str | Path | None) -> list[dict[str, Any]]:
    if path is None:
        return []
    payload = load_json(path)
    items = payload.get("baselines", payload) if isinstance(payload, Mapping) else payload
    if not isinstance(items, list):
        raise ValueError("literature baseline registry must be a list or {'baselines': [...]}")
    return [literature_baseline_to_row(item) for item in items]


def build_benchmark_card(
    *,
    model_name: str,
    cfg: str,
    ckpt: str,
    video_quality: Mapping[str, Any],
    native3d: Mapping[str, Any] | None,
    rows: Sequence[Mapping[str, Any]],
    literature_baselines: Sequence[str] = (),
) -> dict[str, Any]:
    mode = video_quality.get("mode", {})
    native_mode = native3d.get("mode", {}) if isinstance(native3d, Mapping) else {}
    return {
        "name": "WM3D Formal World-Model Benchmark Card",
        "version": "v1",
        "model": model_name,
        "cfg": cfg,
        "ckpt": ckpt,
        "protocol": {
            "video_quality": {
                "metric_protocol": mode.get("metric_protocol"),
                "fvd_protocol": mode.get("fvd_protocol"),
                "fvd_backend": mode.get("fvd_backend"),
                "fvd_context_frames": mode.get("fvd_context_frames"),
                "split": mode.get("split"),
                "balanced_datasets": mode.get("balanced_datasets"),
                "max_batches": mode.get("max_batches"),
                "max_batches_per_dataset": mode.get("max_batches_per_dataset"),
                "paper_scale": "SSIM and LPIPS are also emitted as x100 to match WorldVLA/RynnVLA tables.",
            },
            "native3d_action": {
                "source": "wm3d_v3.eval.world3d_claim_eval",
                "variants": native_mode.get("variants"),
                "motion_threshold": native_mode.get("motion_threshold"),
                "balanced_datasets": native_mode.get("balanced_datasets"),
            },
        },
        "counts": {
            "video_quality": video_quality.get("counts", {}),
            "native3d": native3d.get("counts", {}) if isinstance(native3d, Mapping) else {},
        },
        "subset": video_quality.get("subset", {}),
        "literature_baselines": list(literature_baselines),
        "leaderboard_rows": [dict(row) for row in rows],
        "claim_boundary": {
            "same_harness_comparison": "paper-strong",
            "internal_baseline_comparison": "paper-strong",
            "literature_protocol_comparison": "context-only",
            "why": (
                "Only same_harness rows share the same samples, horizon, renderer, and metric implementation. "
                "literature_protocol rows are official external numbers but are not strict apples-to-apples unless rerun here."
            ),
        },
    }


def _normalize_row(row: Mapping[str, Any]) -> dict[str, Any]:
    out = {field: row.get(field) for field in ROW_FIELDS}
    for key, value in list(out.items()):
        if key in {
            "num_videos",
            "fvd",
            "psnr",
            "ssim_raw",
            "ssim_x100",
            "lpips_raw",
            "lpips_x100",
            "rgb_l1",
            "motion_rgb_l1",
            "motion_region_depth_l1",
            "motion_region_depth_change_l1",
            "depth_change_l1",
            "depth_change_cos",
            "real_action_depth_win_rate",
            "real_action_motion_region_depth_win_rate",
            "real_action_token_win_rate",
        }:
            out[key] = _round_or_none(_as_float(value))
    return out


def _format_cell(value: Any, digits: int = 2) -> str:
    if value is None:
        return "-"
    if isinstance(value, float):
        return f"{value:.{digits}f}"
    return str(value)


def build_markdown_table(rows: Sequence[Mapping[str, Any]]) -> str:
    lines = [
        "| Model | Suite | Compare | FVD↓ | PSNR↑ | SSIM↑ (x100) | LPIPS↓ (x100) | Native-3D | Action win↑ |",
        "|---|---|---:|---:|---:|---:|---:|---:|---:|",
    ]
    for row in rows:
        lines.append(
            "| "
            + " | ".join(
                [
                    str(row.get("model", "")),
                    str(row.get("suite", "")),
                    str(row.get("comparison_type", "")),
                    _format_cell(row.get("fvd")),
                    _format_cell(row.get("psnr")),
                    _format_cell(row.get("ssim_x100")),
                    _format_cell(row.get("lpips_x100")),
                    _format_cell(row.get("motion_region_depth_l1"), digits=4),
                    _format_cell(row.get("real_action_depth_win_rate"), digits=3),
                ]
            )
            + " |"
        )
    lines.append("")
    lines.append(
        "Note: `same_harness` and `internal_baseline` rows share this repo's samples and metric implementation. "
        "`literature_protocol` rows are official external numbers for context and require rerunning the external model through this harness for strict apples-to-apples comparison."
    )
    return "\n".join(lines) + "\n"


def write_csv(rows: Sequence[Mapping[str, Any]], path: str | Path) -> None:
    out = Path(path)
    out.parent.mkdir(parents=True, exist_ok=True)
    with out.open("w", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=ROW_FIELDS, extrasaction="ignore")
        writer.writeheader()
        for row in rows:
            writer.writerow({field: row.get(field) for field in ROW_FIELDS})


def write_outputs(
    *,
    out_dir: str | Path,
    card: Mapping[str, Any],
    rows: Sequence[Mapping[str, Any]],
) -> dict[str, str]:
    out = Path(out_dir)
    out.mkdir(parents=True, exist_ok=True)
    card_path = out / "benchmark_card.json"
    table_path = out / "paper_table.md"
    csv_path = out / "leaderboard_rows.csv"
    card_path.write_text(json.dumps(card, indent=2, sort_keys=True))
    table_path.write_text(build_markdown_table(rows))
    write_csv(rows, csv_path)
    return {
        "benchmark_card": str(card_path),
        "paper_table": str(table_path),
        "leaderboard_rows": str(csv_path),
    }


def _load_all_literature(paths: Iterable[str | Path]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for path in paths:
        rows.extend(load_literature_baselines(path))
    return rows


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--video_quality_json", type=Path, required=True)
    parser.add_argument("--native3d_json", type=Path, default=None)
    parser.add_argument("--out_dir", type=Path, required=True)
    parser.add_argument("--model_name", default="WM3D-1B-stage2")
    parser.add_argument("--suite", default="WM3D-OXE-val")
    parser.add_argument("--cfg", required=True)
    parser.add_argument("--ckpt", required=True)
    parser.add_argument("--literature_baselines", type=Path, action="append", default=[])
    return parser.parse_args()


def main() -> None:
    args = parse_args()
    video = load_json(args.video_quality_json)
    native = load_json(args.native3d_json) if args.native3d_json else None
    rows = build_our_rows(video, native, model_name=args.model_name, suite=args.suite)
    rows.extend(_load_all_literature(args.literature_baselines))
    card = build_benchmark_card(
        model_name=args.model_name,
        cfg=str(args.cfg),
        ckpt=str(args.ckpt),
        video_quality=video,
        native3d=native,
        rows=rows,
        literature_baselines=[str(p) for p in args.literature_baselines],
    )
    outputs = write_outputs(out_dir=args.out_dir, card=card, rows=rows)
    print(json.dumps(outputs, indent=2, sort_keys=True))


if __name__ == "__main__":
    main()
